      border-color: var(--accent);
      opacity: .8;
    }

    main { padding-block: 4rem 5rem; }
    section + section { margin-top: 6rem; }

    .eyebrow {
      margin: 0 0 .65rem;
      color: var(--accent);
      font-size: .78rem;
      font-weight: 750;
      letter-spacing: .16em;
