    }

    .section-intro {
      max-width: 43rem;
      margin: 1rem 0 2.5rem;
      color: var(--secondary);
      font-size: 1.1rem;
    }

    .member-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
      gap: 1.5rem;
    }

    .member-card {
      display: flex;
      min-width: 0;
      flex-direction: column;
      align-items: flex-start;
      padding: 1.5rem;
      border: 1px solid var(--line);
      border-radius: 1.25rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .member-avatar {
      display: block;
      width: 8rem;
      height: 8rem;
      margin-bottom: 1.2rem;
      border: 1px solid var(--line);
      border-radius: 50%;
      object-fit: cover;
      background: var(--bg);
    }

    .member-card h3 {
      margin: 0;
      font-size: 1.5rem;
      letter-spacing: -.035em;
      line-height: 1.2;
    }

    .study {
      margin: .55rem 0 1rem;
      color: var(--secondary);
      font-size: .92rem;
      font-weight: 600;
    }

    .bio {
      margin: 0;
      color: var(--text);
      font-size: .94rem;
    }

    .fun-fact {
      margin: .9rem 0 1.25rem;
      color: var(--secondary);
      font-size: .9rem;
    }

    .hot-take {
      margin: auto 0 0;
      padding: .65rem .8rem;
      border-radius: .65rem;
      background: var(--accent);
      color: #fff;
      font-size: .84rem;
      font-weight: 650;
      line-height: 1.45;
    }

    .future-panel {
      position: relative;
      overflow: hidden;
      padding: clamp(1.5rem, 5vw, 3.5rem);
      border: 1px solid var(--line);
      border-radius: 1.5rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .future-panel .section-intro { margin-bottom: 1.8rem; }

    .future-copy {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.5rem 2.5rem;
    }

    .future-copy p {
      margin: 0;
      color: var(--secondary);
    }

    .future-note {
      grid-column: 1 / -1;
      padding-top: 1.2rem;
      border-top: 1px solid var(--line);
      color: var(--text) !important;
      font-weight: 650;
    }

    footer {
      padding: 1.5rem 1rem;
      border-top: 1px solid var(--line);
      color: var(--secondary);
      text-align: center;
      font-size: .85rem;
    }

    footer p { margin: 0; }

    @media (max-width: 700px) {
      .wrap { width: calc(100% - 2rem); }
      .header-inner {
        flex-direction: column;
        gap: 1rem;
        padding-block: 1.25rem 3.5rem;
