  <script>
    (() => {
      const button = document.getElementById("theme-toggle");
      const icon = button.querySelector(".theme-icon");
      const label = button.querySelector(".theme-label");

      function updateButton(theme) {
        const night = theme === "dark";
        button.setAttribute("aria-label", night ? "Switch to day mode" : "Switch to night mode");
        icon.textContent = night ? "☀" : "☾";
        label.textContent = night ? "Day mode" : "Night mode";
      }

      updateButton(document.documentElement.getAttribute("data-theme"));

      button.addEventListener("click", () => {
        const current = document.documentElement.getAttribute("data-theme");
        const next = current === "dark" ? "light" : "dark";
        document.documentElement.setAttribute("data-theme", next);
        updateButton(next);
        try {
          localStorage.setItem("upb-theme", next);
        } catch (_) {}
      });
    })();
  </script>
